preflightFailures.command:
$ErrorActionPreference='Stop'
$scopePath='D:/Unity/UnityProj/FightMatch/docs/system-design/2026-09-17/demo-014-scope.json'
$s=Get-Content -LiteralPath $scopePath -Raw | ConvertFrom-Json -AsHashtable -DateKind String
foreach($row in @($s.before.files)+@($s.jointCodeFreeze.files)+@($s.preRetrySnapshot.newMetaFiles)){if((Get-FileHash -LiteralPath ('D:/Unity/UnityProj/FightMatch/'+$row.path) -Algorithm SHA256).Hash.ToLowerInvariant() -cne $row.sha256){throw ('Frozen input changed: '+$row.path)}}
$processes=@(Get-Process -Name Unity -ErrorAction SilentlyContinue); if($processes.Count){throw ('BLOCKED: Unity already running: '+($processes.Id -join ','))}
if((Get-FileHash -LiteralPath 'D:/Unity/UnityProj/FightMatch/FMDemoB09-EditMode.xml' -Algorithm SHA256).Hash.ToLowerInvariant() -cne $s.baselineTests.sha256){throw 'B09 baseline XML changed'}
$exe='D:/Unity/UnityClient/2022.3.18f1/Editor/Unity.exe'
$argsList=@('-batchmode','-nographics','-projectPath','D:/Unity/UnityProj/FightMatch','-runTests','-testPlatform','EditMode','-testResults','D:/Unity/UnityProj/FightMatch/FMDemoB10-EditMode.xml','-logFile','D:/Unity/UnityProj/FightMatch/Logs/FMDemoB10Tests.log')
if((Test-Path -LiteralPath 'D:/Unity/UnityProj/FightMatch/Logs/FMDemoB10Tests.log') -or (Test-Path -LiteralPath 'D:/Unity/UnityProj/FightMatch/FMDemoB10-EditMode.xml')){throw 'Original test artifact already exists; preserve it before retry'}
$started=[DateTime]::UtcNow.ToString('o')
$s.preTestSnapshot=[ordered]@{capturedAtUtc=$started;fileCount=453;canonicalSha256=$s.preRetrySnapshot.canonicalSha256;old433Unchanged=$true;frozenSourcesUnchanged=$true;newMetaFiles=$s.preRetrySnapshot.newMetaFiles;jointFreezeSha256=$s.jointCodeFreeze.canonicalSha256}
[IO.File]::WriteAllText($scopePath,($s | ConvertTo-Json -Depth 100 -Compress),[Text.UTF8Encoding]::new($false))
$p=Start-Process -FilePath $exe -ArgumentList $argsList -WindowStyle Hidden -PassThru -Wait
$p.WaitForExit();if($null -eq $p.ExitCode){throw 'Unity Process.ExitCode unavailable'}
$ended=[DateTime]::UtcNow.ToString('o');$log='D:/Unity/UnityProj/FightMatch/Logs/FMDemoB10Tests.log'
$run=[ordered]@{kind='EditMode';startedAtUtc=$started;completedAtUtc=$ended;pid=$p.Id;exitCode=$p.ExitCode;executable=$exe;arguments=$argsList;command=($exe+' '+($argsList -join ' '));windowStyle='Hidden';passThru=$true;wait=$true;processesBefore=@();stdout='';stderr='';outputCapture='Start-Process emits only its Process object to this PowerShell pipeline; Unity application output is retained in the specified logFile.';jointFreezeSha256=$s.jointCodeFreeze.canonicalSha256;artifact=[ordered]@{path='Logs/FMDemoB10Tests.log';sha256=(Get-FileHash -LiteralPath $log -Algorithm SHA256).Hash.ToLowerInvariant();bytes=(Get-Item -LiteralPath $log).Length;compilerErrors=@(Select-String -LiteralPath $log -Pattern 'error CS[0-9]+').Count;compilerWarnings=@(Select-String -LiteralPath $log -Pattern 'warning CS[0-9]+').Count}}
$s.validationRuns=@($s.validationRuns)+@($run)
[IO.File]::WriteAllText($scopePath,($s | ConvertTo-Json -Depth 100 -Compress),[Text.UTF8Encoding]::new($false))
$run | ConvertTo-Json -Depth 6
exit $p.ExitCode
